CREATE TABLE users (id INT PRIMARY KEY AUTO_INCREMENT, email VARCHAR(250) NOT NULL, pass_hash VARCHAR(255) NOT NULL);
CREATE TABLE products (id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(250) NOT NULL, price INT NOT NULL);
CREATE TABLE cart (id INT PRIMARY KEY AUTO_INCREMENT, user_id INT NOT NULL, product_id INT NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id), FOREIGN KEY (product_id) REFERENCES products(id));
CREATE TABLE orders (id INT PRIMARY KEY AUTO_INCREMENT, user_id INT NOT NULL, total INT NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id));
